    objs.push(agua);
    // piezas con profundidad: el mismo orden de dibujo que los objetos viejos
    D.piezas.forEach((p, i) => objs.push(s.add.image(p[1], p[2], K.piezas, 'p' + i).setOrigin(0, 0).setDepth(p[3])));
